def match(orders):
    trades = []
    buy_book = []  # List of (price, arrival_time, id, qty) - sorted by price desc, then arrival_time asc
    sell_book = []  # List of (price, arrival_time, id, qty) - sorted by price asc, then arrival_time asc

    arrival_time = 0
    order_map = {}  # id -> (side, 'limit'/'ioc'/'market', price or None, qty, arrival_time)

    for order in orders:
        arrival_time += 1

        if order[0] == 'cancel':
            order_id = order[1]
            if order_id in order_map:
                side, order_type, price, qty, arr_time = order_map[order_id]
                if order_type == 'limit':
                    if side == 'buy':
                        buy_book[:] = [(p, a, oid, q) for p, a, oid, q in buy_book if oid != order_id]
                    else:
                        sell_book[:] = [(p, a, oid, q) for p, a, oid, q in sell_book if oid != order_id]
                del order_map[order_id]
        else:
            order_type = order[0]
            order_id = order[1]
            side = order[2]
            qty = order[4] if order_type == 'market' else order[4]

            if order_type == 'market':
                price = None
                order_map[order_id] = (side, order_type, price, qty, arrival_time)
            else:
                price = order[3]
                order_map[order_id] = (side, order_type, price, qty, arrival_time)

            remaining_qty = qty

            if side == 'buy':
                # Match against sell_book
                i = 0
                while i < len(sell_book) and remaining_qty > 0:
                    sell_price, sell_arr_time, sell_id, sell_qty = sell_book[i]

                    # Check if this sell can be matched
                    if order_type == 'market' or price >= sell_price:
                        match_qty = min(remaining_qty, sell_qty)
                        trades.append([order_id, sell_id, sell_price, match_qty])
                        remaining_qty -= match_qty
                        sell_book[i] = (sell_price, sell_arr_time, sell_id, sell_qty - match_qty)

                        if sell_book[i][3] == 0:
                            sell_book.pop(i)
                            del order_map[sell_id]
                        else:
                            i += 1
                    else:
                        break

                # Add remaining to buy_book if it's a limit order
                if remaining_qty > 0 and order_type == 'limit':
                    buy_book.append((price, arrival_time, order_id, remaining_qty))
                    buy_book.sort(key=lambda x: (-x[0], x[1]))
                elif remaining_qty > 0:
                    # ioc or market order - discard remainder
                    del order_map[order_id]

            else:  # side == 'sell'
                # Match against buy_book
                i = 0
                while i < len(buy_book) and remaining_qty > 0:
                    buy_price, buy_arr_time, buy_id, buy_qty = buy_book[i]

                    # Check if this buy can be matched
                    if order_type == 'market' or price <= buy_price:
                        match_qty = min(remaining_qty, buy_qty)
                        trades.append([buy_id, order_id, buy_price, match_qty])
                        remaining_qty -= match_qty
                        buy_book[i] = (buy_price, buy_arr_time, buy_id, buy_qty - match_qty)

                        if buy_book[i][3] == 0:
                            buy_book.pop(i)
                            del order_map[buy_id]
                        else:
                            i += 1
                    else:
                        break

                # Add remaining to sell_book if it's a limit order
                if remaining_qty > 0 and order_type == 'limit':
                    sell_book.append((price, arrival_time, order_id, remaining_qty))
                    sell_book.sort(key=lambda x: (x[0], x[1]))
                elif remaining_qty > 0:
                    # ioc or market order - discard remainder
                    del order_map[order_id]

    return trades

